<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d42b1e;
    --blue: #1a3f8f;
    --yellow: #f2c500;
    --black: #111111;
    --white: #ffffff;
    --grey: #e8e8e8;
    --line: 10px;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: "Archivo", Arial, sans-serif;
    background: var(--white);
    color: var(--black);
    line-height: 1.5;
  }
  .frame {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto;
    min-height: 100vh;
  }
  /* The painting, rebuilt in CSS */
  .painting {
    grid-column: 1;
    grid-row: 1 / 3;
    display: grid;
    grid-template-columns: 1fr 1.4fr 1fr;
    grid-template-rows: 1.6fr 1fr;
    background: var(--white);
    border: var(--line) solid var(--black);
    border-right: none;
    min-height: 100vh;
  }
  .painting .cell { border: var(--line) solid var(--black); }
  .painting .white-a { grid-column: 1; grid-row: 1; background: var(--white); }
  .painting .red    { grid-column: 2 / 4; grid-row: 1; background: var(--red); }
  .painting .white-b { grid-column: 1; grid-row: 2; background: var(--white); }
  .painting .blue   { grid-column: 1; grid-row: 2; background: var(--blue); }
  .painting .white-c { grid-column: 2; grid-row: 2; background: var(--white); }
  .painting .yellow { grid-column: 3; grid-row: 2; background: var(--yellow); }
  /* Text side */
  .content {
    grid-column: 2;
    grid-row: 1 / 3;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 2.2rem;
    padding: clamp(1.5rem, 5vw, 4rem);
    border-left: var(--line) solid var(--black);
  }
  .kicker {
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    font-size: 0.8rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }
  .kicker .swatch { display: inline-block; width: 1.1em; height: 1.1em; }
  h1 {
    font-weight: 900;
    font-size: clamp(1.9rem, 4.2vw, 3.4rem);
    line-height: 1.05;
    text-transform: uppercase;
  }
  .meta {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    border: var(--line) solid var(--black);
  }
  .meta div {
    padding: 0.9rem 1rem;
    border-right: var(--line) solid var(--black);
  }
  .meta div:last-child { border-right: none; }
  .meta dt {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 700;
    color: #555;
  }
  .meta dd { font-weight: 700; font-size: 1.05rem; margin-top: 0.2rem; }
  .prose p { max-width: 52ch; margin-bottom: 1rem; }
  .prose p:last-child { margin-bottom: 0; }
  .prose strong { font-weight: 700; }
  .cta {
    display: inline-block;
    align-self: flex-start;
    background: var(--black);
    color: var(--white);
    text-decoration: none;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-size: 0.85rem;
    padding: 1rem 1.6rem;
    border: var(--line) solid var(--black);
    transition: background 0.15s, color 0.15s;
  }
  .cta:hover { background: var(--red); border-color: var(--red); }
  .cta small { display: block; font-weight: 400; letter-spacing: 0; text-transform: none; margin-top: 0.3rem; }
  @media (max-width: 820px) {
    .frame { grid-template-columns: 1fr; grid-template-rows: auto auto; }
    .painting { grid-column: 1; grid-row: 1; min-height: 55vh; border-right: var(--line) solid var(--black); }
    .content { grid-column: 1; grid-row: 2; border-left: none; border-top: var(--line) solid var(--black); }
  }
</style>
</head>
